body.script:
const $=s=>document.querySelector(s), svg=$('#logo'), aim=$('#aim'), shaft=$('#shaft'), rip=$('#rip');
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

/* aim */
let cur=-42,target=-42,active=false;
addEventListener('pointermove',e=>{const r=svg.getBoundingClientRect();active=true;target=Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2))*180/Math.PI});
document.documentElement.addEventListener('mouseleave',()=>active=false);
(function tick(now){
  const idle=reduce?-42:-42+Math.sin(now/1400)*5, tg=active?target:idle;
  cur+=(((tg-cur+540)%360)-180)*.12;
  aim.setAttribute('transform','translate(150 150) rotate('+cur.toFixed(2)+')');
  requestAnimationFrame(tick);
})(0);

/* fire */
function fire(){
  shaft.animate([{transform:'translateX(0)'},{transform:'translateX(-18px)',offset:.3},{transform:'translateX(24px)',offset:.55},{transform:'translateX(0)'}],{duration:650,easing:'cubic-bezier(.2,.7,.2,1)'});
  rip.animate([{transform:'scale(1)',opacity:.95},{transform:'scale(9)',opacity:0}],{duration:800,easing:'ease-out'});
}
svg.addEventListener('click',fire);
svg.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fire()}});

/* typewriter */
const lines=[...document.querySelectorAll('.line')];
const caret=Object.assign(document.createElement('span'),{className:'caret'});
let run=0;
async function typeAll(){
  const id=++run;
  lines.forEach(l=>l.querySelector('.typed').replaceChildren());
  for(const l of lines){
    const full=l.dataset.t, box=l.querySelector('.typed'), tn=document.createTextNode('');
    box.replaceChildren(tn,caret);
    if(reduce){tn.data=full;continue}
    for(let i=1;i<=full.length;i++){
      if(id!==run) return;
      tn.data=full.slice(0,i);
      await sleep(+l.dataset.d*(.7+Math.random()*.7));
    }
    await sleep(350);
  }
}
document.querySelector('.stack').addEventListener('click',e=>{if(e.target.closest('.line'))typeAll()});
(document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve()).then(()=>setTimeout(typeAll,300));
